#include <stdio.h>

int lcs(const char *a, const char *b, int i, int j) {
    if (i == 0 || j == 0) {
        return 0;
    }
    if (a[i - 1] == b[j - 1]) {
        return 1 + lcs(a, b, i - 1, j - 1);
    }
    int x = lcs(a, b, i - 1, j);
    int y = lcs(a, b, i, j - 1);
    return x > y ? x : y;
}

int main() {
    printf("%d\n", lcs("AGGTAB", "GXTXAYB", 6, 7));
    return 0;
}

